{
  "title": "Shared To-Do List",
  "body": "<div class="card"><div class="head"><h1>Shared To-Do List</h1><p class="sub">Add tasks, tick them off, keep track together.</p></div><div class="add-row"><input id="newitem" type="text" placeholder="Add a task…" /><button id="addbtn" type="button">Add</button></div><ul id="list" class="list"></ul><div id="empty" class="empty">All clear — nothing on the list.</div><div class="foot"><span id="count" class="count"></span></div></div>",
  "css": "body { margin:0; padding:24px; background:#f2f4f8; font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif; color:#1f2430; } .card { max-width:520px; margin:0 auto; background:#ffffff; border-radius:16px; box-shadow:0 10px 30px rgba(20,30,60,.10); overflow:hidden; } .head { padding:22px 24px 14px; background:linear-gradient(135deg,#5b8cff 0%,#7b5cff 100%); color:#fff; } .head h1 { margin:0; font-size:20px; letter-spacing:.2px; } .sub { margin:4px 0 0; font-size:13px; opacity:.85; } .add-row { display:flex; gap:10px; padding:16px 24px; border-bottom:1px solid #eef0f5; } #newitem { flex:1; padding:10px 12px; font-size:14px; border:1px solid #d8dce6; border-radius:10px; outline:none; } #newitem:focus { border-color:#5b8cff; box-shadow:0 0 0 3px rgba(91,140,255,.15); } #addbtn { padding:10px 18px; font-size:14px; font-weight:600; color:#fff; background:#5b8cff; border:none; border-radius:10px; cursor:pointer; } #addbtn:hover { background:#4a7af5; } .list { list-style:none; margin:0; padding:8px 12px; } .todo-row { display:flex; align-items:center; gap:10px; padding:10px 12px; border-radius:10px; } .todo-row:hover { background:#f6f8fc; } .todo-row input[type="checkbox"] { width:18px; height:18px; accent-color:#5b8cff; cursor:pointer; } .todo-text { flex:1; font-size:14px; } .todo-row.done .todo-text { text-decoration:line-through; color:#9aa1b1; } .del-btn { border:none; background:transparent; color:#c2c7d4; font-size:18px; line-height:1; cursor:pointer; padding:4px 8px; border-radius:8px; } .del-btn:hover { color:#e5484d; background:#fdecec; } .empty { padding:18px 24px; font-size:13px; color:#9aa1b1; text-align:center; } .foot { padding:12px 24px 18px; } .count { display:inline-block; font-size:12px; font-weight:600; color:#5b8cff; background:#eef3ff; padding:5px 12px; border-radius:999px; }",
  "scripts": [
    "if (!state.todos) {
  state.todos = [
    { id: 1, text: "Pick a destination for the weekend trip", done: false },
    { id: 2, text: "Book a place to stay (hotel, cabin, or campsite)", done: false },
    { id: 3, text: "Make a packing list and check the weather forecast", done: false }
  ];
  state.nextId = 4;
  state.draft = "";
}
const render = () => {
  const list = root.byId["list"];
  list.children = state.todos.map((t) => {
    const row = { tag: "li", attrs: { id: "row-" + t.id, "class": "todo-row" + (t.done ? " done" : "") }, text: "", children: [] };
    const check = { tag: "input", attrs: { id: "check-" + t.id, type: "checkbox" }, text: "", children: [], on: {} };
    if (t.done) { check.attrs.checked = "checked"; }
    check.on.click = () => {
      const item = state.todos.find((x) => x.id === t.id);
      if (item) { item.done = !item.done; }
      render();
    };
    const label = { tag: "span", attrs: { id: "text-" + t.id, "class": "todo-text" }, text: t.text, children: [] };
    const del = { tag: "button", attrs: { id: "del-" + t.id, "class": "del-btn", type: "button" }, text: "×", children: [], on: {} };
    del.on.click = () => {
      state.todos = state.todos.filter((x) => x.id !== t.id);
      render();
    };
    row.children = [check, label, del];
    return row;
  });
  const n = state.todos.filter((t) => !t.done).length;
  root.byId["count"].text = n === 1 ? "1 item left" : n + " items left";
  root.byId["newitem"].attrs.value = state.draft || "";
  root.byId["empty"].attrs.style = state.todos.length === 0 ? "" : "display:none";
};
render();
const inputNode = root.byId["newitem"];
inputNode.on = inputNode.on || {};
inputNode.on.input = (e) => { state.draft = e.value; root.byId["newitem"].attrs.value = e.value; };
const addBtn = root.byId["addbtn"];
addBtn.on = addBtn.on || {};
addBtn.on.click = () => {
  const text = (state.draft || "").trim();
  if (text.length > 0) {
    state.todos.push({ id: state.nextId, text: text, done: false });
    state.nextId = state.nextId + 1;
    state.draft = "";
  }
  render();
};"
  ]
}
